export const STORAGE_KEY='aventura-v1';
export const domains={reading:'Lectura',comprehension:'Comprensión',counting:'Conteo',sum:'Sumas',subtract:'Restas'};
export function defaultState(){return {version:1,settings:{readingLevel:1,countingBand:20,mathRange:10,font:1,sound:true,motion:true,duration:12,adaptive:true},history:[],pending:null,session:null};}
export function loadState(storage){try{const s=JSON.parse(storage.getItem(STORAGE_KEY));if(s?.version!==1||!Array.isArray(s.history)||![1,2,3].includes(s.settings?.readingLevel))return defaultState();return {...defaultState(),...s,settings:{...defaultState().settings,...s.settings}};}catch{return defaultState();}}
export function recordAttempt(state,entry){state.history.push({at:new Date().toISOString(),errors:0,help:false,...entry,correct:entry.domain==='reading'?null:entry.correct});if(state.history.length>2000)state.history.splice(0,state.history.length-2000);}
export function recommendLevel(state,domain,current,max){const recent=state.history.filter(x=>x.domain===domain&&(x.levelIndex??current)===current).slice(-5);if(recent.length<5)return current;if(recent.every(x=>x.correct===true&&!x.help&&!x.errors))return Math.min(current+1,max);if(recent.filter(x=>x.help||x.errors>=2).length>=3)return Math.max(0,current-1);return current;}
export function matchesOrder(tokens,solutions){const norm=x=>x.join(' ').toLocaleLowerCase('es').replace(/[.,¡!¿?]/g,'').replace(/\s+/g,' ').trim();return solutions.some(s=>norm(s)===norm(tokens));}
export function numberName(n){const small=['cero','uno','dos','tres','cuatro','cinco','seis','siete','ocho','nueve','diez','once','doce','trece','catorce','quince','dieciséis','diecisiete','dieciocho','diecinueve','veinte','veintiuno','veintidós','veintitrés','veinticuatro','veinticinco','veintiséis','veintisiete','veintiocho','veintinueve'];if(n<30)return small[n];if(n===100)return 'cien';const tens=['','','','treinta','cuarenta','cincuenta','sesenta','setenta','ochenta','noventa'];return tens[Math.floor(n/10)]+(n%10?' y '+small[n%10]:'');}
export function choiceNumbers(answer,max=100){return [...new Set([Math.max(0,answer-1),answer,Math.min(max,answer+1),Math.max(0,answer-2)])].sort((a,b)=>a-b);}
